import{Et as e,Ot as t,n,qt as r}from"./chunks/framework.C8R-a4p3.js";var i=JSON.parse(`{"title":"Industrial PLC — Where Software Meets Steel","description":"PLC programming in Ladder and Structured Text (IEC 61131-3), HMI design, SCADA logic — automation on real production lines.","frontmatter":{"title":"Industrial PLC — Where Software Meets Steel","description":"PLC programming in Ladder and Structured Text (IEC 61131-3), HMI design, SCADA logic — automation on real production lines."},"headers":[],"relativePath":"en/skills/plc/index.md","filePath":"en/skills/plc/index.md"}`),a={name:`en/skills/plc/index.md`};function o(n,i,a,o,s,c){return r(),e(`div`,null,[...i[0]||=[t(`<h1 id="industrial-plc-—-where-software-meets-steel" tabindex="-1">Industrial PLC — Where Software Meets Steel <a class="header-anchor" href="#industrial-plc-—-where-software-meets-steel" aria-label="Permalink to “Industrial PLC — Where Software Meets Steel”">​</a></h1><p>Before web APIs, there were wires. Industrial automation taught me that software has consequences you can hear — a bad line of logic does not throw an exception, it stops a production line or pinches a finger. I program PLCs in <strong>Ladder Diagram</strong> and <strong>Structured Text</strong> under IEC 61131-3, and I design the HMIs operators actually use.</p><h2 id="what-i-do-on-the-floor" tabindex="-1">What I do on the floor <a class="header-anchor" href="#what-i-do-on-the-floor" aria-label="Permalink to “What I do on the floor”">​</a></h2><table tabindex="0"><thead><tr><th>Area</th><th>Practice</th></tr></thead><tbody><tr><td>Logic</td><td>Ladder (LD) for discrete control; Structured Text (ST) for math and sequences.</td></tr><tr><td>HMI</td><td>Screens operators can read at a glance, in their language, with honest alarms.</td></tr><tr><td>SCADA thinking</td><td>Tag naming, alarm rationalization, data logging that survives audits.</td></tr><tr><td>Safety</td><td>Interlocks first, convenience second — always.</td></tr></tbody></table><p>Automation made me a better software engineer in three specific ways: I respect <strong>state machines</strong> (a line is one giant state machine), I write <strong>defensive code</strong> (sensors lie, contacts weld), and I document as if the next reader is standing next to a running machine — because sometimes they are.</p><blockquote><p>In industrial control, uptime is measured in tons, not nines.</p></blockquote>`,6)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};